//! What the `bdd` target needs beside cucumber-rs: its command line,
//! which scenarios it runs, and an executor to drive the run on the
//! current thread.

use std::any::{Any, TypeId, type_name};
use std::collections::HashMap;
use std::ffi::OsStr;
use std::fmt;
use std::future::Future;
use std::path::Path;
use std::pin::pin;
use std::process::Command;
use std::sync::Arc;
use std::task::{Context, Poll, Wake, Waker};
use std::thread::{self, Thread};

use cucumber::gherkin::tagexpr::TagOperation;
use cucumber::tag::Ext as _;

use crate::PENDING;

/// Which scenarios a run selects.
#[derive(Debug, Clone, Default)]
pub struct Options {
    /// A tag expression such as `@ENG-24`, from `--tags`.
    pub tags: Option<TagOperation>,
    /// Name filters, as `cargo test <filter>` passes them: a scenario is
    /// selected when its name contains one, or one names its tag.
    pub filters: Vec<String>,
    /// Filters from `--skip`, as libtest takes them: a scenario one of
    /// them matches, the way a name filter matches, is left out.
    pub skips: Vec<String>,
}

/// libtest's flags that take no value, accepted and ignored so that
/// `cargo test -- <flag>` across the workspace still runs the target.
const LIBTEST_FLAGS: [&str; 7] = [
    "--nocapture",
    "--show-output",
    "--quiet",
    "-q",
    "--ignored",
    "--include-ignored",
    "--exact",
];

/// libtest's flags that take a value, accepted and ignored likewise.
const LIBTEST_VALUED: [&str; 2] = ["--test-threads", "--color"];

/// Reads the target's command line: `--tags EXPR` (or `-t`), name
/// filters, `--skip FILTER`, and the libtest flags cargo may pass on.
///
/// # Errors
///
/// Fails on an unknown flag, a flag missing its value, or a tag
/// expression that does not parse.
pub fn parse_args(args: &[String]) -> Result<Options, String> {
    let mut options = Options::default();
    let mut args = args.iter();
    while let Some(arg) = args.next() {
        let (flag, inline) = match arg.split_once('=') {
            Some((flag, value)) if flag.starts_with('-') => (flag, Some(value.to_owned())),
            _ => (arg.as_str(), None),
        };
        let mut value = || {
            inline
                .clone()
                .or_else(|| args.next().cloned())
                .ok_or(format!("{flag} needs a value"))
        };
        match flag {
            "--tags" | "-t" => {
                let expr = value()?;
                options.tags = Some(expr.parse().map_err(|e| format!("--tags {expr:?}: {e}"))?);
            }
            "--skip" => options.skips.push(value()?),
            f if LIBTEST_VALUED.contains(&f) => drop(value()?),
            f if LIBTEST_FLAGS.contains(&f) => {}
            f if f.starts_with('-') => return Err(format!("unknown flag {f:?}")),
            _ => options.filters.push(arg.clone()),
        }
    }

    Ok(options)
}

impl Options {
    /// Whether a run with these options runs the scenario `name`
    /// carrying `tags`, written without their `@`. A pending scenario is
    /// never run: it is declared, not written.
    #[must_use]
    pub fn selects<'a>(&self, name: &str, tags: impl Iterator<Item = &'a String> + Clone) -> bool {
        let matches_filter = |f: &String| {
            name.contains(f.as_str()) || tags.clone().any(|t| t == f.trim_start_matches('@'))
        };

        !tags.clone().any(|t| t == PENDING)
            && self
                .tags
                .as_ref()
                .is_none_or(|expr| expr.eval(tags.clone()))
            && (self.filters.is_empty() || self.filters.iter().any(matches_filter))
            && !self.skips.iter().any(matches_filter)
    }
}

/// Wakes the thread that drives a future.
struct Unpark(Thread);

impl Wake for Unpark {
    fn wake(self: Arc<Self>) {
        self.0.unpark();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        self.0.unpark();
    }
}

/// Drives `future` to completion on the current thread, parking it
/// while the future waits. cucumber-rs needs no more of an executor
/// than this.
pub fn block_on<F: Future>(future: F) -> F::Output {
    let waker = Waker::from(Arc::new(Unpark(thread::current())));
    let mut cx = Context::from_waker(&waker);
    let mut future = pin!(future);
    loop {
        if let Poll::Ready(out) = future.as_mut().poll(&mut cx) {
            return out;
        }
        thread::park();
    }
}

/// The variable that marks the runner's own process as isolated: its
/// value is the home the parent created for it.
pub const ISOLATED_HOME: &str = "CAIRN_BDD_HOME";

/// Whether a process with `HOME` set to `home`, and the marker set to
/// `marker`, runs isolated (ENG-14): the marker names its `HOME`, and
/// that home sits under the system's temporary directory `temp`, so an
/// exported marker cannot point the scenarios at a real home.
#[must_use]
pub fn is_isolated(home: Option<&OsStr>, marker: Option<&OsStr>, temp: &Path) -> bool {
    match (home, marker) {
        (Some(home), Some(marker)) => home == marker && Path::new(home).starts_with(temp),
        _ => false,
    }
}

/// Points `command` at `home`: its `HOME`, a `CAIRN_HOME` inside it,
/// and the marker that says the process is isolated.
pub fn isolate<'a>(command: &'a mut Command, home: &Path) -> &'a mut Command {
    command
        .env("HOME", home)
        .env("CAIRN_HOME", home.join(".cairn"))
        .env(ISOLATED_HOME, home)
}

/// A child's exit status code as this process's exit code: a signal,
/// or a code outside 0 to 255, is a failure.
#[must_use]
pub fn exit_code(code: Option<i32>) -> u8 {
    code.and_then(|c| u8::try_from(c).ok()).unwrap_or(1)
}

/// The sections' own state beside a scenario's world, one value per
/// type: created on first use and the same value for the rest of the
/// scenario. A section declares a struct for what its scenarios track
/// and never adds a field to the world.
#[derive(Default)]
pub struct Sections(HashMap<TypeId, Box<dyn Any>>);

impl Sections {
    /// The section state of type `T`.
    pub fn get<T: Default + 'static>(&mut self) -> &mut T {
        let slot = self
            .0
            .entry(TypeId::of::<T>())
            .or_insert_with(|| Box::new(T::default()));
        // The map is keyed by the type, so the value is always a T.
        slot.downcast_mut()
            .unwrap_or_else(|| unreachable!("section {} holds another type", type_name::<T>()))
    }
}

impl fmt::Debug for Sections {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Sections({})", self.0.len())
    }
}

#[cfg(test)]
mod tests;

    /// The writers of this node's own seats, whose seat keys it holds.
    /// The slice reads origin from them: their events `witnessed`
    /// here, every other writer's `peer` (RCL-09).
    own_writers: BTreeSet<String>,
    held: BTreeMap<String, BTreeMap<u64, Event>>,
    ranges: BTreeMap<String, BTreeSet<(u64, u64)>>,
    /// The erasure requests this node's principal applied (PEER-11),
    /// each named by the tombstone the slice stands in for it with. A
    /// tombstone in one of the node's own writers is its own purge and
    /// needs none.
    erasure_requests: BTreeSet<Address>,
}

impl Node {
    /// A node holding nothing yet, whose own writers are those named.
    pub fn new(dir: &Path, own_writers: &[&str]) -> Result<Node> {
        std::fs::create_dir_all(dir)?;
        Ok(Node {
            dir: dir.to_path_buf(),
            own_writers: own_writers.iter().map(|s| s.to_string()).collect(),
            held: BTreeMap::new(),
            ranges: BTreeMap::new(),
            erasure_requests: BTreeSet::new(),
        })
    }

    /// Receives a segment: verifies it, merges it with what is held,
    /// applies the tombstones that apply here, and stores the writer.
    pub fn receive(&mut self, segment: &Segment) -> Result<()> {
        segment.check()?;
        let held = self.held.entry(segment.writer.clone()).or_default();
        for e in &segment.events {
            let seq = e.header.seq;
            if let Some(h) = held.get(&seq)
                && h.hash != e.hash
            {
                return Err(Error::new(format!(
                    "{:?}: a second, different event at a held seq, refused",
                    e.address()
                )));
            }
            let links = [
                seq.checked_sub(1)
                    .and_then(|p| held.get(&p))
                    .map(|p| (Some(p.hash), e.header.prev_hash)),
                held.get(&(seq + 1))
                    .map(|n| (n.header.prev_hash, Some(e.hash))),
            ];
            if links.into_iter().flatten().any(|(want, got)| want != got) {
                return Err(Error::new(format!(
                    "{:?}: does not chain to what is held",
                    e.address()
                )));
            }
        }
        for e in &segment.events {
            match held.get_mut(&e.header.seq) {
                Some(h) if h.body.is_none() => h.body = e.body.clone(),
                Some(_) => {}
                None => {
                    held.insert(e.header.seq, e.clone());
                }
            }
        }
        let range = (segment.first(), segment.last());
        self.ranges
            .entry(segment.writer.clone())
            .or_default()
            .insert(range);
        let mut dirty = self.apply_tombstones();
        dirty.extend(segment.events.iter().map(Event::address));
        self.store(&dirty)
    }

    /// Applies an erasure request: this node's principal erases what
    /// the tombstone at `tombstone` names (PEER-11). The slice stands
    /// in for the request, a signed event, with the tombstone itself.
    pub fn apply_erasure_request(&mut self, tombstone: &Address) -> Result<()> {
        match self.event(tombstone) {
            Some(e) if e.header.kind == "tombstone" => {}
            _ => {
                return Err(Error::new(format!(
                    "{tombstone:?} is no tombstone held here"
                )));
            }
        }
        self.erasure_requests.insert(tombstone.clone());
        let dirty = self.apply_tombstones();
        self.store(&dirty)
    }

    /// Erases the content and commitment key of every event an
    /// applicable tombstone names; returns the addresses it erased.
    fn apply_tombstones(&mut self) -> BTreeSet<Address> {
        let named: Vec<Address> = self
            .events()
            .into_iter()
            .filter(|t| t.header.kind == "tombstone")
            .filter(|t| {
                self.own_writers.contains(&t.header.writer)
                    || self.erasure_requests.contains(&t.address())
            })
            .filter_map(|t| t.body.as_ref())
            .flat_map(|b| purged_addresses(&b.content))
            .collect();
        let mut erased = BTreeSet::new();
        for a in named {
            if let Some(e) = self.held.get_mut(&a.writer).and_then(|w| w.get_mut(&a.seq))
                && e.body.take().is_some()
            {
                erased.insert(a);
            }
        }
        erased
    }

    pub fn event(&self, a: &Address) -> Option<&Event> {
        self.held.get(&a.writer)?.get(&a.seq)
    }

    /// Every held event, in (writer, seq) order.
    pub fn events(&self) -> Vec<&Event> {
        self.held.values().flat_map(|w| w.values()).collect()
    }

    /// How the writer's events reached this node (RCL-09). Origin is
    /// per event; in the slice every event of a writer reaches a node
    /// the same way: recorded live by its own writers, received for
    /// any other.
    pub fn origin(&self, writer: &str) -> &'static str {
        if self.own_writers.contains(writer) {
            "witnessed"
        } else {
            "peer"
        }
    }

    /// The node's deployment mode as the writer recorded it, in its
    /// first event.
    fn deployment_mode(&self, writer: &str) -> Option<&str> {
        let first = self.held.get(writer)?.get(&1)?;
        if first.header.kind != "deployment_mode" {
            return None;
        }
        first
            .body
            .as_ref()?
            .content
            .get("deployment_mode")?
            .as_str()
    }

    /// The default trust policy (PRV-02), for the classes the slice
    /// records: on the recording node only, structural, `operator` and
    /// `harness_meta` events, and `user` events while the recorded
    /// deployment mode is `interactive`. Everything else is untrusted.
    pub fn trust(&self, e: &Event) -> &'static str {
        let w = &e.header.writer;
        let trusted = self.origin(w) == "witnessed"
            && match e.header.provenance.as_str() {
                "structural" | "operator" | "harness_meta" => true,
                "user" => self.deployment_mode(w) == Some("interactive"),
                _ => false,
            };
        if trusted { "trusted" } else { "untrusted" }
    }

    /// Writes each held segment holding a changed address, as the node
    /// now holds it, under `segments/<writer>/<first>-<last>.seg`.
    fn store(&self, changed: &BTreeSet<Address>) -> Result<()> {
        for (writer, ranges) in &self.ranges {
            let dir = self.dir.join("segments").join(writer);
            std::fs::create_dir_all(&dir)?;
            for &(first, last) in ranges {
                let lo = Address {
                    writer: writer.clone(),
                    seq: first,
                };
                let hi = Address {
                    writer: writer.clone(),
                    seq: last,
                };
                if changed.range(lo..=hi).next().is_none() {
                    continue;
                }
                let events: Vec<Event> = self.held[writer]
                    .range(first..=last)
                    .map(|(_, e)| e.clone())
                    .collect();
                let s = Segment {
                    writer: writer.clone(),
                    events,
                };
                write_atomic(
                    &dir.join(format!("{first:012}-{last:012}.seg")),
                    &s.encode(),
                )?;
            }
        }
        Ok(())
    }

    /// Rebuilds the index file, holding the search index and room state,
    /// from the held writers and the node's own writers alone (ADM-08),
    /// as a new file that replaces the old one; returns its path.
    pub fn rebuild(&self) -> Result<PathBuf> {
        let path = self.dir.join("index.db");
        let next = self.dir.join("index.db.next");
        let _ = std::fs::remove_file(&next);
        index::build(&next, self, &room::derive(self))?;
        std::fs::rename(&next, &path)?;
        Ok(path)
    }

    /// Every file the node stores.
    pub fn files(&self) -> Result<Vec<PathBuf>> {
        let mut out = Vec::new();
        let mut dirs = vec![self.dir.clone()];
        while let Some(d) = dirs.pop() {
            for entry in std::fs::read_dir(&d)? {
                let p = entry?.path();
                if p.is_dir() {
                    dirs.push(p)
                } else {
                    out.push(p)
                }
            }
        }
        out.sort();
        Ok(out)
    }
}

fn write_atomic(path: &Path, bytes: &[u8]) -> Result<()> {
    let tmp = path.with_extension("tmp");
    std::fs::write(&tmp, bytes)?;
    std::fs::rename(&tmp, path)?;
    Ok(())
}

